"""Build Laminar-Lab from actual frozen controlled results. Never synthesize scores."""
from pathlib import Path
import json,html,hashlib,statistics,sys
sys.path.insert(0,str(Path(__file__).resolve().parent))
from academic_project_style import CSS,icon
ROOT=Path(__file__).resolve().parents[1];P=ROOT/'projects/laminar-lab';E=html.escape
GIT='https://github.com/LlewynLune/ai-portfolio/tree/main/projects/laminar-lab'
COLORS={'synchronous':'#59687a','async_ratio':'#386d86','async_no_ratio':'#c58d55','async_bound2':'#7c7b92'}

def table(rows):
 keys=['seed','mode','probe','elapsed','max_stale','drops']
 return '<div class="table-scroll"><table class="paper-table"><thead><tr>'+''.join('<th>'+E(x)+'</th>' for x in ['Seed','Policy','Fixed probe token score','Elapsed incl. injected delays (s)','Max consume staleness','Discarded groups'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(str(r[k]))+'</td>' for k in keys)+'</tr>' for r in rows)+'</tbody></table></div>'

def plot(runs,width=800,height=480):
 s=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {height}" role="img" aria-label="Three seeds and four RL policies, controlled run"><rect width="800" height="480" fill="white"/><g font-family="Arial, sans-serif" fill="#3b4653"><text x="38" y="34" font-size="23">Laminar-Lab / Controlled RL runs</text><text x="38" y="60" font-size="13">Fixed toy-task probe · 3 seeds · 4 policies · not an independent holdout</text>']
 for t in range(6):
  y=350-t*50;s.append(f'<path d="M62 {y}H762" stroke="#e4e7eb"/><text x="28" y="{y+5}" font-size="12">{t*.2:.1f}</text>')
 for si,seed in enumerate([7,19,41]):
  for mi,mode in enumerate(COLORS):
   r=next(r for r in runs if r['seed']==seed and r['mode']==mode);val=r['final']['heldout_token_accuracy'];x=95+si*225+mi*42;h=val*250
   s.append(f'<rect x="{x}" y="{350-h}" width="30" height="{h}" fill="{COLORS[mode]}"/><text x="{x+15}" y="{342-h}" font-size="10" text-anchor="middle">{val:.2f}</text>')
  s.append(f'<text x="{155+si*225}" y="377" font-size="14" text-anchor="middle">seed {seed}</text>')
 for i,(mode,color) in enumerate(COLORS.items()):s.append(f'<rect x="{42+i*187}" y="412" width="10" height="10" fill="{color}"/><text x="{57+i*187}" y="422" font-size="11">{mode}</text>')
 s.append('<text x="38" y="460" font-size="12">All results preserved. Speed ≠ convergence; performance varies by seed.</text></g></svg>');return ''.join(s)

def shell(title,body):return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+CSS+'''\npre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.7 ui-monospace,monospace;border:1px solid #ddd;padding:16px;max-height:450px;overflow:auto}.explorer-controls{display:flex;gap:14px;align-items:end;flex-wrap:wrap}.explorer-controls label{font-size:13px;display:flex;gap:5px;flex-direction:column}select,input,button{max-width:100%;padding:8px;border:1px solid #bbb;background:white;color:#333;border-radius:3px}.note{font-size:13px;color:#777}.event-chart{border:1px solid #ddd;overflow:auto}#detail-panel{max-height:650px}.publication-header{padding-bottom:20px}button:disabled{opacity:.5}canvas{max-width:100%}
</style></head><body><nav class="project-top"><a href="../../index.html#experiments">← Yu Yue / Portfolio</a><a href="project.html">Laminar-Lab</a></nav><header class="publication-header"><h1 class="publication-title">Laminar-Lab</h1><h2 class="publication-subtitle">Trajectory-Level Async RL<br>Version Consistency &amp; Policy Staleness</h2><div class="publication-authors">Yu Yue（于跃）</div><p class="publication-affiliation">个人研究与工程实验</p><p class="publication-note">AI 辅助实现 · 非论文发表或生产项目 · 非官方完整复现</p><div class="publication-links"><a class="resource" href="project.html">Project</a><a class="resource" href="evidence.html">Evidence Explorer</a><a class="resource" href="'''+GIT+'''">Code</a><a class="resource" href="https://github.com/verl-project/laminar">Official Laminar</a></div></header><main>'''+body+'''</main><footer class="project-footer">个人 AI 辅助研究 · 实际小模型训练 · 合成任务 · 不复制官方实验数字<br><a href="../../index.html">Portfolio</a><a href="'''+GIT+'''">Reproduction</a></footer></body></html>'''

def build():
 summary=json.loads((P/'artifacts/controlled/summary.json').read_text());runs=summary['runs'];audit=json.loads((P/'artifacts/audit.json').read_text());rows=[{'seed':r['seed'],'mode':r['mode'],'probe':f"{r['final']['heldout_token_accuracy']:.3f}",'elapsed':f"{r['elapsed_s']:.3f}",'max_stale':r['staleness_max'],'drops':r['discarded_groups']} for r in runs];svg=plot(runs);(ROOT/'assets/portfolio/laminar-lab-evidence.svg').write_text(svg)
 body='''<section class="project-section narrow"><h2>Introduction</h2><p class="abstract">这不是把异步流程画成一张图：本项目实际运行一个小型自回归策略的采样和 RL 更新，让 rollout 与 learner 解耦，逐条记录版本、旧策略概率与消费时陈旧度。核心研究问题是：取消全局 barrier 后，系统更快是否真的学习更好？</p><p>公开依据是 <a href="https://arxiv.org/html/2510.12633v1">Laminar 论文 v1</a> 和 <a href="https://github.com/verl-project/laminar">官方开源仓库</a>。论文强调 trajectory-level asynchrony、CPU Relay 与同版本 repack。本项目仅检验可在本机运行的机制，不宣称复现 UCX、RDMA、vLLM、GPU KV 迁移或 1024 GPU 成绩。</p></section>
<section class="project-section"><h2>Overview</h2><figure class="figure"><img src="../../assets/portfolio/laminar-lab-evidence.svg" alt="全3种子4策略实际训练结果"><figcaption>artifacts/controlled 实测固定探针；全种子对照，不选择最好的一次。有限语法有大量 prompt 重合，不能当独立留出泛化。</figcaption></figure></section>
<section class="project-section narrow"><h2>Method</h2><div class="method-steps"><div><small>01</small>MLP 自回归采样<br>四回答同版本组</div><div><small>02</small>不可变 Relay<br>FIFO / 背压</div><div><small>03</small>Clipped token ratio<br>Group advantage / KL</div><div><small>04</small>版本 / 进程恢复<br>同版本 packing</div></div><p>13→24→4 tanh MLP，先监督学习 copy，RL 学习每符号加一取模。每 prompt 四回答，奖励为符号匹配率；组内标准化 reward advantage。四种策略、三个种子，每次 40 learner updates，每个 batch 六个组、四次真实梯度更新。reference 冻结、每个轨迹 snapshot 固定，所有行为 logprob 和模型 hash 保留。</p><p>token ratio clipping 只是一种 GRPO-like surrogate：不是无偏 full-sequence IS，不是 V-trace，不作通用收敛保证。主训练按完整 prompt group 入队，比官方逐 trajectory admission 更粗。同步与异步都使用四个 worker；透明注入每 token 1.5ms I/O 延迟和每 update 2ms 控制开销。</p></section>
<section class="project-section"><h2>Experimental Results</h2><p>下面逐种子展示 controlled 修正版全部运行。原探索批次异步含 worker 延迟倍率，不能作为公平比较；保存在 artifacts/runs。修正版移除倍率、纠正无 ratio 损失记录，单独运行而非回填旧数字。</p>'''+table(rows)+'''<p class="caption">probe 字段由原始 heldout_* 字段读取：实际是已反复监控的固定学习探针，有限 prompt 重叠比例见 audit.json，不能称独立测试。Elapsed 包含明确注入的 sleep 与 Python overhead，不是 GPU throughput。</p><h3>What did not work</h3><p>所有策略均未稳定学会四符号任务，种子和陈旧度策略带来明显差异。异步 ratio 的速度、学习分数和显式 bound 的丢弃量须分别看；不写“异步必然更好”。同语法确定性 parser 能达到全正确，说明神经网络并非此玩具任务的必要方案。</p></section>
<section class="project-section narrow"><h2>Systems Evidence</h2><p>300 个自写 packing 场景核验版本隔离、双容量约束与 cache/request 守恒。另直接执行固定官方 revision 的未修改 pure repack planner，100 个场景检查同版本与 KV 上限。官方当前 planner 和论文双约束不完全相同，因此独立报告；没有执行官方 RL 完整 test suite。</p><p>6 次真实 os._exit 子进程退出后重启，逐一验证 SQLite 已提交 prefix、不可变权重、同版本完整轨迹和唯一 experience 记录。恢复重算 prefix，不是假称 GPU KV 直接迁移；本地唯一插入不是分布式 exactly-once。</p></section>
<section class="project-section narrow"><h2>Interactive Demo</h2><p>打开 Evidence Explorer，可选运行、查看每轮 reward / ratio / KL / clip、轨迹组与实际时间事件，并导出当前证据。页面内联原 JSON，离线可打开；它不假装在浏览器重新执行 Python 训练。</p><div class="section-links"><a class="resource" href="evidence.html">Open Evidence Explorer</a></div></section>
<section class="project-section narrow"><h2>Limitations &amp; Reproducibility</h2><p>30 次小模型实训包含 12 次旧探索、12 次公平控制及 6 次取消 token sleep 的敏感性；同任务、有限种子、无独立泛化结论。MLP 不是大语言模型，暂未接入公开大模型 LoRA-RL；本机无 CUDA/RDMA 集群，完整 Laminar 部署没有完成。前沿框架学习、实跑机制和本人既往字节业务经历严格分开。</p><p>下一步需要独立长序列语法、真正可训练的小型语言模型、逐 token partial store、relay 读栅栏与完整故障训练恢复，而不是多画一个界面。<a href="'''+GIT+'''">源码、协议与边界</a>全部公开；官方固定版本：19333d00b8d794a145a07b6c082a1fa3cf84c42e。</p></section>'''
 (P/'project.html').write_text(shell('Laminar-Lab | Async RL Mechanisms',body))
 data=[]
 for path in sorted((P/'artifacts/controlled').glob('*-*.json')):data.append(json.loads(path.read_text()))
 sensitivity=json.loads((P/'artifacts/no-token-delay/summary.json').read_text()) if (P/'artifacts/no-token-delay/summary.json').exists() else {}
 ood=json.loads((P/'artifacts/ood-length.json').read_text())
 sensitivity_rows=[{'seed':r['seed'],'mode':r['mode'],'probe':f"{r['final']['heldout_token_accuracy']:.3f}",'elapsed':f"{r['elapsed_s']:.3f}",'max_stale':r['staleness_max'],'drops':r['discarded_groups']} for r in sensitivity['runs']]
 extra='<section class="project-section"><h2>Delay Sensitivity &amp; Length OOD</h2><p>取消每 token 延迟，仍保留每 update 2ms 控制开销。另6次真实训练：异步 rollout 更快带来最高消费陈旧度5，部分种子学习更差。这是同已见语法的追加敏感性，不是新独立实验任务。</p>'+table(sensitivity_rows)+'<p>冻结12个 controlled 模型，对12/16长度做128个同一新探针；训练长度最大8，因此没有完全相同 prompt。所有条件均未稳定泛化，确定性 parser 仍全正确。该追加探针在读过初始结果后运行，不宣称盲测。</p><div class="table-scroll"><table class="paper-table"><thead><tr><th>Run</th><th>Length OOD token score</th><th>Exact sequence</th></tr></thead><tbody>'+''.join('<tr><td>'+E(r['run'])+'</td><td>'+f"{r['mean_token_accuracy']:.3f}"+'</td><td>'+f"{r['exact_sequence_rate']:.3f}"+'</td></tr>' for r in ood['runs'])+'</tbody></table></div></section>'
 (P/'project.html').write_text(shell('Laminar-Lab | Async RL Mechanisms',body+extra))
 records={'runs':data,'audit':audit,'ood':ood,'sensitivity':sensitivity,'recovery':json.loads((P/'artifacts/system/recovery.json').read_text()),'upstream':json.loads((P/'artifacts/system/upstream-contracts.json').read_text())}
 ui='''<section class="project-section"><h2>Frozen Training Evidence</h2><p>选择实跑记录。所有图、组与时间轴读取同一个完整 JSON；静态浏览器不会训练模型，不调用付费 API。</p><div class="explorer-controls"><label>Run<select id="run-select"></select></label><label>Record type<select id="view-select"><option value="updates">Learner updates</option><option value="groups">Trajectory groups</option><option value="events">Actual timing events</option><option value="systems">System contracts</option></select></label><label>Find<input id="search" placeholder="group / version / hash"></label><button id="export">Export run JSON</button></div><p id="run-facts" class="note"></p><div id="learning-chart" class="event-chart"></div><div class="explorer-controls"><button id="prev">Previous</button><span id="page-label"></span><button id="next">Next</button></div><div id="record-list" class="table-scroll"></div><h3>Selected original record</h3><pre id="detail-panel"></pre><h3>Probe overlap &amp; data boundary</h3><p>字段名 heldout_* 是早期命名，实际固定学习探针存在大量完全重合 prompt。没有严格独立 holdout。短语法 parser 本来就能解全，不包装成真实语言推理能力。</p><pre id="overlap"></pre></section>'''
 js=r'''<script>
const DATA=REPLACE_DATA;
let runIndex=0,view='updates',page=0,query='',filtered=[];
const $=id=>document.getElementById(id);DATA.runs.forEach((r,i)=>{const o=document.createElement('option');o.value=i;o.textContent=`seed ${r.summary.seed} · ${r.summary.mode}`;$('run-select').appendChild(o)});
function draw(r){const vals=r.updates,points=vals.map((u,i)=>`${48+i*680/Math.max(1,vals.length-1)},${245-u.heldout_token_accuracy*200}`).join(' '),reward=vals.map((u,i)=>`${48+i*680/Math.max(1,vals.length-1)},${245-u.reward*200}`).join(' ');$('learning-chart').innerHTML=`<svg viewBox="0 0 800 300" role="img" aria-label="Fixed probe and sampled reward"><rect width="800" height="300" fill="white"/><path d="M48 40V245H760" stroke="#aaa" fill="none"/><polyline points="${points}" stroke="#386d86" stroke-width="2" fill="none"/><polyline points="${reward}" stroke="#c58d55" stroke-width="2" fill="none"/><text x="48" y="278" font-family="Arial" font-size="12">blue: fixed probe token score / orange: sampled training reward / x: learner update</text></svg>`}
function source(){const r=DATA.runs[runIndex];if(view==='systems')return [{recovery:DATA.recovery,upstream_planner:DATA.upstream,sensitivity:DATA.sensitivity,length_ood:DATA.ood}];return r[view]}
function render(){const r=DATA.runs[runIndex];$('run-facts').textContent=`Consumed ${r.summary.consumed_groups} groups; ${r.summary.actual_sampled_tokens_consumed} sampled tokens; max consume staleness ${r.summary.staleness_max}; discarded ${r.summary.discarded_groups}. Time includes artificial delays. Each group is four trajectories, not four independent prompts.`;draw(r);filtered=source().filter(x=>JSON.stringify(x).toLowerCase().includes(query));const pages=Math.max(1,Math.ceil(filtered.length/12));page=Math.min(page,pages-1);$('page-label').textContent=`${page+1} / ${pages} · ${filtered.length} records`;$('prev').disabled=page===0;$('next').disabled=page>=pages-1;const table=document.createElement('table');table.className='paper-table';table.innerHTML='<thead><tr><th>Index</th><th>Record</th><th>Open original</th></tr></thead>';const tbody=document.createElement('tbody');filtered.slice(page*12,page*12+12).forEach((x,i)=>{const tr=document.createElement('tr');const n=document.createElement('td');n.textContent=page*12+i+1;tr.appendChild(n);const t=document.createElement('td');t.textContent=view==='updates'?`update ${x.update} · reward ${x.reward.toFixed(3)} · probe ${x.heldout_token_accuracy.toFixed(3)}`:view==='groups'?`group ${x.gid} · version ${x.policy_version} · length ${x.length}`:view==='events'?`${x.kind} · ${x.time_s.toFixed(4)}s`:'System records';tr.appendChild(t);const td=document.createElement('td');const b=document.createElement('button');b.textContent='Inspect';b.onclick=()=>{$('detail-panel').textContent=JSON.stringify(x,null,2)};td.appendChild(b);tr.appendChild(td);tbody.appendChild(tr)});table.appendChild(tbody);$('record-list').replaceChildren(table);$('detail-panel').textContent=JSON.stringify(filtered[page*12]||{message:'No matching record'},null,2);$('overlap').textContent=JSON.stringify(DATA.audit.find(a=>a.file===`${r.summary.seed}-${r.summary.mode}.json`),null,2)}
$('run-select').onchange=e=>{runIndex=+e.target.value;page=0;render()};$('view-select').onchange=e=>{view=e.target.value;page=0;render()};$('search').oninput=e=>{query=e.target.value.toLowerCase();page=0;render()};$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};$('export').onclick=()=>{const r=DATA.runs[runIndex],url=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`laminar-${r.summary.seed}-${r.summary.mode}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)};render();
</script>'''
 js=js.replace('REPLACE_DATA',json.dumps(records,ensure_ascii=False,allow_nan=False).replace('</','<\\/'))
 (P/'evidence.html').write_text(shell('Laminar-Lab | Actual RL Evidence',ui+js));print('Built Laminar landing and',len(data),'frozen run explorer; bytes',(P/'evidence.html').stat().st_size)
 checks={str(f.relative_to(P)):hashlib.sha256(f.read_bytes()).hexdigest() for f in P.rglob('*') if f.is_file() and '__pycache__' not in f.parts and f.name!='checksums.json'};(P/'artifacts/checksums.json').write_text(json.dumps(checks,indent=2))
if __name__=='__main__':build()
